{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people to watch TV with refreshments.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A surface or arrangement used to hold drinks and snacks for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "table",
          "surface",
          "tray"
        ],
        "required_properties": [
          "holds_drinks",
          "holds_snacks"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "remote",
          "controller"
        ],
        "required_properties": [
          "operates_television"
        ]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "An area or surface where a person sits.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "chair",
          "sofa",
          "seat"
        ],
        "required_properties": [
          "supports_person"
        ]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "A display device showing content for viewing.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "tv",
          "screen"
        ],
        "required_properties": [
          "displays_content"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_setting_near_seating",
        "relation": "near",
        "participant_roles": [
          "refreshment_setting",
          "seating_area"
        ]
      ,
        "required": true
      },
      {
        "id": "control_accessible_to_seating",
        "relation": "accessible_to",
        "participant_roles": [
          "entertainment_control",
          "seating_area"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshment_settings",
        "operation": "place_refreshment_setting_near_seating_area",
        "participant_roles": [
          "refreshment_setting",
          "seating_area"
        ],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "move_entertainment_control_to_accessible_location",
        "participant_roles": [
          "entertainment_control",
          "seating_area"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "Wooden desk in foreground",
          "visual_description": "Large wooden table with cups and plates on top."
        }
      ],
      "entertainment_control": [
        {
          "label": "Black remote",
          "visual_description": "Small black object on the wooden desk."
        }
      ],
      "seating_area": [
        {
          "label": "Left armchair",
          "visual_description": "Dark cushioned chair with wooden frame."
        },
        {
          "label": "Right armchair",
          "visual_description": "Dark cushioned chair with wooden frame."
        }
      ],
      "television": [
        {
          "label": "Wall mounted TV",
          "visual_description": "Black rectangular screen mounted on the wall."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_storage",
        "label": "Wooden desk interior",
        "visual_description": "Drawers or shelves visible beneath the desk surface in side/top views.",
        "reason": "Could contain additional settings or equipment."
      },
      {
        "id": "side_table_shelves",
        "label": "Side table shelves",
        "visual_description": "Open shelving unit next to the right chair.",
        "reason": "Could hold supplementary refreshment items."
      },
      {
        "id": "console_surface",
        "label": "Console table under TV",
        "visual_description": "Narrow table placed against the wall below the TV.",
        "reason": "Could serve as a secondary surface for controls or snacks."
      }
    ],
    "inspection_order": [
      "desk_storage",
      "side_table_shelves",
      "console_surface"
    ]
  }
  ,
